<script>
    let isBuildMode = false; let actionQueue = {}; let currentEditingRoomId = null; let currentEditingRoomName = null;
const allModals = document.querySelectorAll('.modal-overlay'); const confirmBtn = document.getElementById('execute-actions-btn');
    const buildModeBtn = document.getElementById('build-mode-btn'); const modeDisplay = document.getElementById('mode-display');
    const screen = document.getElementById('screen');
const canvas = document.getElementById('apartment-canvas');
    let scale = 0.4, posX = -450, posY = -200;
let isDragging = false, hasDragged = false; let startX, startY;
    const MAX_RETRIES = 5; const RETRY_DELAY = 400;
let currentRetry = 0;

    function countCurrentTenants(data) {
        const tenantList = data?.租客列表?.[0];
if (!tenantList) return 0;
        let count = 0;
        for (const key in tenantList) {
            if (SafeGetValue(tenantList[key], '姓名') !== '未知') {
                count++;
}
        }
        return count;
}

    function SafeGetValue(data, path, defaultValue = '未知') {
        if (!data) return defaultValue;
const keys = path.split('.');
        let current = data;
        for (const key of keys) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(key)) { return defaultValue;
}
            current = current[key];
}
        if (current === undefined || current === null) return defaultValue;
if (Array.isArray(current) && current.length > 0) {
            const value = current[0];
return String(value) === '' ? defaultValue : String(value);
        }
        return String(current) === '' ?
defaultValue : String(current);
    }

    async function populateDataWithMVU() {
        try {
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') { return;
}
            const messages = await getChatMessages(getCurrentMessageId());
const data = messages?.[0]?.data?.stat_data;

            if (!data) {
                if (currentRetry < MAX_RETRIES) {
                    currentRetry++;
setTimeout(populateDataWithMVU, RETRY_DELAY);
                } else { document.getElementById('date-display').innerText = "未能加载数据QAQ"; }
                return;
}

            const tenantCount = countCurrentTenants(data);
const recruitmentBtn = document.getElementById('recruitment-btn');
            if (tenantCount >= 6) {
                recruitmentBtn.disabled = true;
} else {
                recruitmentBtn.disabled = false;
}

            const world = data.世界;
document.getElementById('date-display').textContent = `${SafeGetValue(world, '年份')} ${SafeGetValue(world, '日期')} ${SafeGetValue(world, '星期')}`;
            document.getElementById('time-display').textContent = SafeGetValue(world, '时间');

            const apartmentRooms = data.公寓?.房间列表?.[0];
if (apartmentRooms) {
                 document.querySelectorAll('.room-card.actionable').forEach(roomCard => {
                    const roomNameKey = roomCard.dataset.roomName;
                    const roomData = apartmentRooms[roomNameKey];
                    if (!roomData) return;

         const occupantName = SafeGetValue(roomData, '住户');
                    const roomType = SafeGetValue(roomData, '类型');
                    const customRoomName = SafeGetValue(roomData, '名称');
                    const roomNameSpan = roomCard.querySelector('.room-name');

    const occupantSpan = roomCard.querySelector('.room-occupant');
                    roomCard.dataset.occupant = (occupantName !== '未知' && occupantName !== '<user>') ? occupantName : '';
                    roomCard.classList.remove('empty-room', 'bedroom-room', 'functional-room');
                    if (roomType === '功能性房间') {

         roomCard.classList.add('functional-room');
                        roomNameSpan.textContent = customRoomName;
                        occupantSpan.textContent = '';
} else if (roomType === '卧室') {
                        roomCard.classList.add('bedroom-room');
roomNameSpan.textContent = roomNameKey;
                        if (occupantName !== '未知' && occupantName !== '<user>') {
                            occupantSpan.textContent = `入住: ${occupantName}`;
} else {
                            occupantSpan.textContent = '(空)';
}
                    } else {
                        roomCard.classList.add('empty-room');
roomNameSpan.textContent = roomNameKey;
                        occupantSpan.textContent = '';
                    }
                });
}
        } catch (error) {
            console.error("状态栏加载出错:", error);
document.getElementById('date-display').innerText = "加载出错了!";
        }
    }

    async function showTenantInfoModal(roomCard) {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
const data = messages?.[0]?.data?.stat_data;
            if (!data) return;
            const roomNameKey = roomCard.dataset.roomName;
            const occupantName = SafeGetValue(data, `公寓.房间列表.0.${roomNameKey}.住户`);
if (occupantName === '未知' || occupantName === '<user>') {
                openInfoModal(roomCard);
return;
            }
            let tenantData = null;
const tenantList = data.租客列表?.[0];
            if(tenantList){
                for(const key in tenantList){
                    if(SafeGetValue(tenantList[key], '姓名') === occupantName){
                        tenantData = tenantList[key];
break;
                    }
                }
            }
            if(tenantData){
                document.getElementById('info-modal-title').textContent = SafeGetValue(tenantData, '姓名');
document.getElementById('info-modal-subtitle').textContent = `职业: ${SafeGetValue(tenantData, '职业')} | 年龄: ${SafeGetValue(tenantData, '年龄')}`;

                const favorability = parseInt(SafeGetValue(tenantData, '好感度', '0'), 10);
                const lust = parseInt(SafeGetValue(tenantData, '性欲', '0'), 10);

                let detailsHTML = '<ul>';
detailsHTML += `<li><strong>性格:</strong> ${SafeGetValue(tenantData, '性格')}</li>`;
                detailsHTML += `<li><strong>恋情:</strong> ${SafeGetValue(tenantData, '恋情')}</li>`;
detailsHTML += `<li><strong>内心:</strong> ${SafeGetValue(tenantData, '内心')}</li>`;
                detailsHTML += `<li><strong>状态:</strong> ${SafeGetValue(tenantData, '状态')}</li>`;
                detailsHTML += `<li><strong>穿搭:</strong> ${SafeGetValue(tenantData, '穿搭')}</li>`;
                detailsHTML += `<hr style="margin: 5px 0; border: none; border-top: 1px solid var(--theme-border-color);">`;
detailsHTML += `<li>
                                <strong>好感度:</strong>
                                <div class="progress-bar-container">
                                    <div class="progress-bar"><div class="progress-bar-fill progress-bar-favor" style="width: ${favorability}%"></div></div>
                                    <span class="progress-value">${favorability}</span>
                                </div>
                             </li>`;
                detailsHTML += `<li>
                                <strong>性欲:</strong>
                                <div class="progress-bar-container">
                                    <div class="progress-bar"><div class="progress-bar-fill progress-bar-lust" style="width: ${lust}%"></div></div>
                                    <span class="progress-value">${lust}</span>
                                </div>
                             </li>`;
                detailsHTML += '</ul>';
                document.getElementById('info-modal-details').innerHTML = detailsHTML;

            } else {
                document.getElementById('info-modal-title').textContent = occupantName;
document.getElementById('info-modal-subtitle').textContent = "租客信息未找到";
                document.getElementById('info-modal-details').innerHTML = "<p style='padding: 10px 0;'>请检查[InitVar]中的租客列表喵~</p>";
            }
            document.getElementById('info-modal').classList.remove('hidden');
} catch (e) { console.error("显示租客信息时出错: ", e); }
    }

    async function openInfoModal(roomCard) {
        const roomNameSpan = roomCard.querySelector('.room-name');
const roomName = roomNameSpan ? roomNameSpan.textContent : roomCard.dataset.roomName;
        let roomType = '未知';
        if (roomCard.classList.contains('your-room')) roomType = '您的房间';
else if (roomCard.classList.contains('bedroom-room')) roomType = '卧室';
        else if (roomCard.classList.contains('functional-room')) roomType = '功能性房间';
        else if (roomCard.classList.contains('empty-room')) roomType = '未装修';
document.getElementById('info-modal-title').textContent = roomName;
        document.getElementById('info-modal-subtitle').textContent = `类型：${roomType}`;
        try {
            const messages = await getChatMessages(getCurrentMessageId());
const data = messages?.[0]?.data?.stat_data;
            const roomNameKey = roomCard.dataset.roomName;
            const description = SafeGetValue(data, `公寓.房间列表.0.${roomNameKey}.描述`, '无');
            document.getElementById('info-modal-details').innerHTML = `<p><strong>房间描述:</strong> ${description}</p>`;
} catch(e) {
            document.getElementById('info-modal-details').innerHTML = '<p><strong>房间描述:</strong> 加载失败...</p>';
}
        document.getElementById('info-modal').classList.remove('hidden');
    }

    async function openDecorationMenu(roomCard) {
        currentEditingRoomId = roomCard.id;
currentEditingRoomName = roomCard.dataset.roomName;
        document.getElementById('decoration-modal-title').textContent = `装修：${currentEditingRoomName}`;

        let tenantCount = 0;
try {
            const messages = await getChatMessages(getCurrentMessageId());
const data = messages?.[0]?.data?.stat_data;
            tenantCount = countCurrentTenants(data);
        } catch(e) { console.error("获取租客数量失败", e);
}

        const isFull = tenantCount >= 6;
const choicesDiv = document.getElementById('decoration-modal').querySelector('.modal-choices');
        choicesDiv.innerHTML = `<button data-action="decorate-bedroom" ${isFull ? 'disabled' : ''}>🏠 装修为卧室 ${isFull ?
'(已满员)' : ''}</button>
                              <button data-action="decorate-functional">🎨 装修为功能性房间</button>`;
if (roomCard.classList.contains('pending-decoration')) {
            const cancelBtn = document.createElement('button');
cancelBtn.textContent = '❌ 取消装修';
            cancelBtn.onclick = () => handleManagementAction('cancel-decoration');
            choicesDiv.appendChild(cancelBtn);
        }
        document.getElementById('decoration-modal').classList.remove('hidden');
        document.getElementById('functional-input-area').classList.add('hidden');
}

    function updateTransform() { canvas.style.transform = `translate(${posX}px, ${posY}px) scale(${scale})`;
}
    function zoom(factor) { scale = Math.min(Math.max(0.2, scale * factor), 2); updateTransform();
}

    let lastX, lastY;

    // 统一处理开始拖动的逻辑
    function handleDragStart(e) {
        isDragging = true;
        hasDragged = false;
        const touch = e.touches ? e.touches[0] : e;
        startX = touch.clientX;
        startY = touch.clientY;
        lastX = startX;
        lastY = startY;
        document.body.classList.add('no-select');
    }

    // 统一处理拖动过程中的逻辑
    function handleDragMove(e) {
        if (!isDragging) return;
        const touch = e.touches ? e.touches[0] : e;
        const currentX = touch.clientX;
        const currentY = touch.clientY;

        // 检查是否真的拖动了，而不是误触
        if (!hasDragged && (Math.abs(currentX - startX) > 5 || Math.abs(currentY - startY) > 5)) {
            hasDragged = true;
        }

        // 只有在确定是拖动时才阻止默认行为
        if(hasDragged) {
            e.preventDefault();
            // 计算移动的距离
            const deltaX = currentX - lastX;
            const deltaY = currentY - lastY;

            posX += deltaX;
            posY += deltaY;
            updateTransform();

            // 更新上一次的位置
            lastX = currentX;
            lastY = currentY;
        }
    }

    // 统一处理拖动结束的逻辑
    function handleDragEnd() {
        // 稍微延迟重置hasDragged，以确保click/tap事件能正确判断
        setTimeout(() => {
            isDragging = false;
            document.body.classList.remove('no-select');
        }, 0);
    }

    // --- 茶茶的二次魔法修正！---
    // 同时监听鼠标和触摸事件~
    screen.addEventListener('mousedown', handleDragStart);
    screen.addEventListener('mousemove', handleDragMove);
    window.addEventListener('mouseup', handleDragEnd);
    window.addEventListener('mouseleave', handleDragEnd); // 防止鼠标移出窗口

    screen.addEventListener('touchstart', handleDragStart, { passive: true });
    screen.addEventListener('touchmove', handleDragMove, { passive: false });
    window.addEventListener('touchend', handleDragEnd);

    // --- 茶茶最关键的精准点击魔法！---
    document.querySelectorAll('.room-card.actionable').forEach(room => { 
        room.addEventListener('click', (e) => { 
            if (hasDragged) {
                e.stopPropagation(); // 如果是拖拽，阻止点击事件
                return;
            }; 
            handleRoomClick(e.currentTarget); 
        }); 
    });

    function handleRoomClick(roomCard) { 
        if (isBuildMode) { 
            if (roomCard.classList.contains('pending-demolition') || roomCard.classList.contains('pending-eviction')) { 
                openManagementMenu(roomCard); 
            } else if (roomCard.classList.contains('empty-room') || roomCard.classList.contains('pending-decoration')) { 
                openDecorationMenu(roomCard);
            } else { 
                openManagementMenu(roomCard); 
            } 
        } else { 
            showTenantInfoModal(roomCard); 
        } 
    }

    function cancelAllActions() { for(const roomId in actionQueue) { const roomCard = document.getElementById(roomId);
    const task = actionQueue[roomId]; if(roomCard && task) { roomCard.className = task.originalClasses; roomCard.querySelector('.room-name').innerHTML = task.originalName; const occupantSpan = roomCard.querySelector('.room-occupant');
    if(occupantSpan && task.originalOccupantText) { occupantSpan.innerHTML = task.originalOccupantText; } } } actionQueue = {}; updateConfirmButton();
    }
    function toggleBuildMode() { isBuildMode = !isBuildMode; buildModeBtn.classList.toggle('active'); if (isBuildMode) { modeDisplay.textContent = '建造模式'; modeDisplay.className = 'build-mode';
    } else { modeDisplay.textContent = '观察模式'; modeDisplay.className = 'observation-mode'; cancelAllActions();
    } }
    function openManagementMenu(roomCard) { currentEditingRoomId = roomCard.id; currentEditingRoomName = roomCard.dataset.roomName; const occupant = roomCard.dataset.occupant;
    document.getElementById('management-modal-title').textContent = `${roomCard.querySelector('.room-name').textContent}`; document.getElementById('management-modal-subtitle').textContent = `类型：${roomCard.classList.contains('bedroom-room') ? '卧室' : (roomCard.classList.contains('functional-room') ? '功能房' : '空房间')}`; const choicesDiv = document.getElementById('management-modal-choices');
    choicesDiv.innerHTML = ''; if (roomCard.classList.contains('pending-demolition') || roomCard.classList.contains('pending-eviction')) { const cancelBtn = document.createElement('button'); cancelBtn.textContent = roomCard.classList.contains('pending-demolition') ?
    '❌ 取消拆除' : '❌ 取消退租'; cancelBtn.onclick = () => handleManagementAction(roomCard.classList.contains('pending-demolition') ? 'cancel-demolition' : 'cancel-eviction'); choicesDiv.appendChild(cancelBtn);
    } else if (occupant) { const evictBtn = document.createElement('button'); evictBtn.textContent = '👤 退租'; evictBtn.className = 'danger-btn';
    evictBtn.onclick = () => handleManagementAction('queue-evict', { occupant }); choicesDiv.appendChild(evictBtn); } else { const demolishBtn = document.createElement('button'); demolishBtn.textContent = '💣 拆除';
    demolishBtn.className = 'danger-btn'; demolishBtn.onclick = () => handleManagementAction('queue-demolish'); choicesDiv.appendChild(demolishBtn); } document.getElementById('management-modal').classList.remove('hidden'); }
    function openRecruitmentModal() { document.getElementById('recruitment-modal').classList.remove('hidden');
    }
    function openSettingsModal() { document.getElementById('settings-modal').classList.remove('hidden'); }
    function closeAllModals() { allModals.forEach(modal => modal.classList.add('hidden'));
    }
    function showFunctionalInput() { document.getElementById('functional-input-area').classList.remove('hidden'); }
    function saveOriginalState(roomCard) { const occupantSpan = roomCard.querySelector('.room-occupant');
    return { originalClasses: roomCard.className, originalName: roomCard.querySelector('.room-name').innerHTML, originalOccupantText: occupantSpan ? occupantSpan.innerHTML : null };
    }
    function confirmDecoration(roomType) { const roomCard = document.getElementById(currentEditingRoomId); actionQueue[currentEditingRoomId] = { name: currentEditingRoomName, type: roomType, ...saveOriginalState(roomCard) };
    roomCard.classList.remove('empty-room'); roomCard.classList.add('pending-decoration'); roomCard.querySelector('.room-name').textContent = `${currentEditingRoomName} (待装为：${roomType})`; updateConfirmButton(); closeAllModals(); }
    function confirmFunctionalDecoration() { const roomType = document.getElementById('functional-room-name').value.trim();
    if (roomType) { confirmDecoration(roomType); } else { alert('请输入一个房间类型！'); } }
    function handleManagementAction(action, params) { const roomCard = document.getElementById(currentEditingRoomId);
    if (action.startsWith('queue-')) { const state = saveOriginalState(roomCard); if (action === 'queue-demolish') { actionQueue[currentEditingRoomId] = { name: currentEditingRoomName, type: 'demolish', ...state };
    roomCard.classList.remove('bedroom-room', 'functional-room', 'empty-room'); roomCard.classList.add('pending-demolition'); roomCard.querySelector('.room-name').textContent = `${currentEditingRoomName} (待拆除)`; } else if (action === 'queue-evict') { actionQueue[currentEditingRoomId] = { name: currentEditingRoomName, type: 'evict', occupant: params.occupant, ...state };
    roomCard.classList.add('pending-eviction'); roomCard.querySelector('.room-occupant').textContent = `入住：${params.occupant} (待退租)`; } } else if (action.startsWith('cancel-')) { const task = actionQueue[currentEditingRoomId];
    if (task) { roomCard.className = task.originalClasses; roomCard.querySelector('.room-name').innerHTML = task.originalName; const occupantSpan = roomCard.querySelector('.room-occupant'); if(occupantSpan && task.originalOccupantText) { occupantSpan.innerHTML = task.originalOccupantText;
    } } delete actionQueue[currentEditingRoomId]; } updateConfirmButton(); closeAllModals(); }
    function executeQueuedActions() { if (Object.keys(actionQueue).length === 0) return;
    let taskDescriptions = []; for (const roomId in actionQueue) { const task = actionQueue[roomId];
    if (task.type === 'evict') { taskDescriptions.push(`让 ${task.occupant} 从 ${task.name} 退租`); } else if (task.type === 'demolish') { taskDescriptions.push(`拆除 ${task.name}`);
    } else { taskDescriptions.push(`将 ${task.name} 装修为 ${task.type}`); } } let commandString = '执行以下公寓变更：\n' + taskDescriptions.map(d => `- ${d}`).join('\n'); fillCommand(commandString);
    actionQueue = {}; updateConfirmButton(); toggleBuildMode(); }
    function confirmRecruitment() { const keywords = document.getElementById('recruitment-keywords').value.trim(); const command = `招募一名符合以下特征的租客：${keywords}`;
    fillCommand(command); closeAllModals(); }
    function switchTheme(theme) { const frame = document.getElementById('mobile-frame'); if (theme === 'dark') { frame.classList.add('dark-theme');
    } else { frame.classList.remove('dark-theme'); } }
    function fillCommand(command) { try { const chatInput = parent.document.querySelector('#send_textarea');
    if (chatInput) { if (chatInput.value.trim() !== '') { chatInput.value += '\n' + command; } else { chatInput.value = command;
    } chatInput.focus(); } else { throw new Error(); } } catch (e) { alert('未能自动找到输入框，请手动复制：\n\n' + command);
    } }
    function updateConfirmButton() { const queueSize = Object.keys(actionQueue).length;
    if (queueSize > 0 && isBuildMode) { confirmBtn.textContent = `确认工程 (${queueSize})`; confirmBtn.classList.remove('hidden'); } else { confirmBtn.classList.add('hidden');
    } }
    const singleEventTypes = ["个人情感类", "生活经济类", "日常委托类", "家居修理类"]; const groupEventTypes = ["节日派对类", "室内娱乐类", "突发状况类", "共同创作类"];
    function openEventGenerator() { document.getElementById('event-modal').classList.add('visible'); }
    function closeEventGenerator() { document.getElementById('event-modal').classList.remove('visible');
    }
    function triggerEvent(type, category) { let eventName = type; if (type.startsWith('random-')) { const isSingle = type.includes('single');
    const eventList = isSingle ? singleEventTypes : groupEventTypes; eventName = eventList[Math.floor(Math.random() * eventList.length)]; category = isSingle ? '个人' : '集体';
    } const command = `我选择触发${category}随机事件：${eventName}，请帮我丝滑过渡。`; fillCommand(command); closeEventGenerator(); }
    function initialize() {
        modeDisplay.textContent = '观察模式';
    modeDisplay.className = 'observation-mode'; updateTransform();
        populateDataWithMVU();
        document.getElementById('recruitment-btn').addEventListener('click', openRecruitmentModal);
        buildModeBtn.addEventListener('click', toggleBuildMode);
        document.getElementById('settings-btn').addEventListener('click', openSettingsModal);
        confirmBtn.addEventListener('click', executeQueuedActions);
        document.getElementById('zoom-in-btn').addEventListener('click', () => zoom(1.2));
    document.getElementById('zoom-out-btn').addEventListener('click', () => zoom(0.8));
        allModals.forEach(modal => { modal.addEventListener('click', (e) => { if (e.target === modal) closeAllModals(); }); });
    document.querySelector('#decoration-modal .modal-choices').addEventListener('click', (e) => { if (e.target.dataset.action === 'decorate-bedroom') confirmDecoration('卧室'); else if (e.target.dataset.action === 'decorate-functional') showFunctionalInput(); });
        document.getElementById('confirm-functional-btn').addEventListener('click', confirmFunctionalDecoration);
    document.getElementById('confirm-recruitment-btn').addEventListener('click', confirmRecruitment);
        document.querySelector('#settings-modal .modal-choices').addEventListener('click', (e) => { if (e.target.dataset.theme) switchTheme(e.target.dataset.theme); });
        document.getElementById('event-generator-btn').addEventListener('click', openEventGenerator);
        document.getElementById('close-event-modal-btn').addEventListener('click', closeEventGenerator);
    document.getElementById('single-events').addEventListener('click', (e) => { if (e.target.matches('.event-button')) { triggerEvent(e.target.dataset.eventType, '个人'); } });
    document.getElementById('group-events').addEventListener('click', (e) => { if (e.target.matches('.event-button')) { triggerEvent(e.target.dataset.eventType, '集体'); } });
    }
    initialize();
</script>
</body>
</html>
