</div>

<div id="companion-data" style="display: none;">$1</div>

<script>
    // 4. 全新的专业指令发送功能
    const triggerQuickReply = (text) => {
        if (!text || text.trim().length === 0) return;
        // 这是一个SillyTavern扩展中常用的函数，用于将文本发送回输入框
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send ${text.trim()}|/trigger`);
        } else {
            // 如果在普通浏览器环境，则用alert模拟
            alert(`模拟发送指令：\n${text}`);
            console.log('SillyTavern环境未检测到. 将发送:', text);
        }
    };

    // 5. 我们自己的、兼容扁平化格式的JS逻辑核心 (完全保留)
    window.onload = function() {
        const rawData = document.getElementById('companion-data').textContent;
        const candidatesContainer = document.getElementById('candidates-container');
        const confirmButton = document.getElementById('confirm-button');
        let selectedCandidateName = null;

        if (!rawData) {
            candidatesContainer.innerHTML = '<p style="text-align:center; color: var(--appSecondaryText); padding: 2rem;">等待AI生成候选人...</p>';
            return;
        }

        const candidates = rawData.split('候选人:').slice(1);
        candidates.forEach(candidateText => {
            const extract = (key) => { const regex = new RegExp(`${key}: "([^"]+)"`); const match = candidateText.match(regex); return match ? match[1] : ''; };
            const name = extract('名字');
            if (!name) return;

            const card = document.createElement('div');
            card.className = 'candidate-card';
            card.addEventListener('click', () => handleCardClick(card, name));

            let tagsHTML = '';
            const tags = extract('标签');
            if (tags) { tags.split('/').forEach(tag => { tagsHTML += `<span class="tag">${tag.trim()}</span>`; }); }

            card.innerHTML = `
                <h3 class="candidate-name">${name}</h3>
                <div class="tags-container">${tagsHTML}</div>
                <div class="details-container">
                    <p><strong>年龄:</strong> ${extract('年龄')}</p>
                    <p><strong>常见穿搭:</strong> ${extract('常见穿搭')}</p>
                    <p><strong>情感状况:</strong> ${extract('情感状况')}</p>
                    <p><strong>简介:</strong> ${extract('简介')}</p>
                </div>
                <div class="quote">“${extract('代表性发言')}”</div>
            `;
            candidatesContainer.appendChild(card);
        });

        function handleCardClick(clickedCard, candidateName) {
            const isAlreadySelected = clickedCard.classList.contains('selected');
            document.querySelectorAll('.candidate-card.selected').forEach(card => card.classList.remove('selected'));
            if (isAlreadySelected) {
                selectedCandidateName = null;
            } else {
                clickedCard.classList.add('selected');
                selectedCandidateName = candidateName;
            }
            updateConfirmButtonState();
        }

        function updateConfirmButtonState() {
            if (selectedCandidateName) {
                confirmButton.disabled = false;
                confirmButton.innerHTML = `<i class="fa fa-check-circle mr-2"></i>确认选择: ${selectedCandidateName}`;
            } else {
                confirmButton.disabled = true;
                confirmButton.innerHTML = `<i class="fa fa-user-plus mr-2"></i>请选择租客 (最多1位)`;
            }
        }

        confirmButton.addEventListener('click', function() {
            if (!this.disabled && selectedCandidateName) {
                const message = `我选择 "${selectedCandidateName}" 作为新租客入住。`;
                triggerQuickReply(message); // 使用新的发送函数
                this.textContent = '指令已发送!';
                this.disabled = true;
            }
        });
    };
</script>

